        nested_oneof: Some(HardwareNestedOneof::Nested(nested_c)),
    };
    let mut expected = Vec::with_capacity(msg.encoded_len());
    msg.encode(&mut expected)
        .expect("synchronous prost encode succeeds");

    let source = tokio_stream::iter(std::iter::once(Ok::<_, Status>(msg.clone())));
    let mut body = pin!(EncodeBody::new_client(
        DsaAsyncProstEncoder::<HardwareProstMessage>::with_work_queue(
            BufferSettings::default(),
            work_queue,
        ),
        source,
        None,
        None,
    ));
    let waker = std::task::Waker::noop();
    let mut cx = Context::from_waker(waker);

    let (frame, pending_polls) = poll_next_frame_with_pending_count(&mut body, &mut cx);
    let data = frame.into_data().expect("got data frame");

    assert!(
        pending_polls > 0,
        "hardware DSA encode completed without yielding"
    );
    assert_eq!(data[0], 0);
    assert_eq!(
        u32::from_be_bytes(data[1..HEADER_SIZE].try_into().unwrap()) as usize,
        expected.len()
    );
    assert_eq!(&data[HEADER_SIZE..], expected.as_slice());

    let decoded =
        HardwareProstMessage::decode(&data[HEADER_SIZE..]).expect("encoded prost message decodes");
    assert_eq!(decoded, msg);

    println!(
        "dsa prost e2e result: payload_len={} frame_len={} pending_polls={} prefix_hex={}",
        expected.len(),
        data.len(),
        pending_polls,
        hex_prefix(&data[HEADER_SIZE..], 32)
    );
}

fn poll_next_frame_with_pending_count<B>(
    body: &mut std::pin::Pin<&mut B>,
    cx: &mut Context<'_>,
) -> (http_body::Frame<Bytes>, usize)
where
    B: Body<Data = Bytes, Error = Status>,
{
    let mut pending_polls = 0;
    for _ in 0..1_000_000 {
        match body.as_mut().poll_frame(cx) {
            Poll::Ready(Some(Ok(frame))) => return (frame, pending_polls),
            Poll::Ready(Some(Err(status))) => panic!("encode failed: {status}"),
            Poll::Ready(None) => panic!("body ended before data"),
            Poll::Pending => {
                pending_polls += 1;
                core::hint::spin_loop();
            }
        }
    }

    panic!("timed out waiting for DSA encode completion")
}

fn hex_prefix(bytes: &[u8], len: usize) -> String {
    let mut out = String::new();
    for byte in bytes.iter().take(len) {
        use core::fmt::Write as _;
        write!(&mut out, "{byte:02x}").expect("write to String");
    }
    out
}

/// Mutable destination used by generated asynchronous Prost encoding.
///
/// The sink exposes a short-lived [`BufMut`] view for protobuf structure
/// writes, and a separate payload-copy hook for `string` / `bytes` field
/// contents. The default CPU sink copies payloads immediately; experimental
/// sinks can return [`Poll::Pending`] while an external copy engine initializes
/// the destination bytes.
pub trait AsyncEncodeSink {
    /// Error produced while starting or completing an asynchronous encode.
    type Error: Send + Sync + 'static;

    /// Borrowed protobuf byte sink for CPU-written keys, lengths, and scalars.
    type BufMut<'a>: BufMut + Send
    where
        Self: 'a;

    /// Per-payload state kept by poll-based generated encoders while a sink
    /// copy is pending.
    type PayloadState: Default + Send;

    /// Converts a Prost capacity error into this sink's error type.
    fn encode_error(error: EncodeError) -> Self::Error;

    /// Returns the byte sink used for CPU-written protobuf structure.
    fn buf_mut(&mut self) -> Self::BufMut<'_>;

    /// Copies a `string` or `bytes` payload into the destination.
    fn poll_put_payload(
        &mut self,
        payload: &[u8],
        state: Pin<&mut Self::PayloadState>,
        cx: &mut Context<'_>,
    ) -> Poll<Result<(), Self::Error>>;

    /// Future-shaped adapter around [`AsyncEncodeSink::poll_put_payload`].
    fn put_payload<'a>(&'a mut self, payload: &'a [u8]) -> PutPayload<'a, Self>
    where
        Self: Sized,
    {
        PutPayload::new(self, payload)
    }
}
